src/components/apps/Game2048.tsx.content:
'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { motion, AnimatePresence } from 'framer-motion';
import { RotateCcw, Trophy } from 'lucide-react';

type Tile = {
  id: number;
  value: number;
  isNew?: boolean;
  isMerged?: boolean;
};

// Colors based on value
const getTileColors = (value: number, isLight: boolean) => {
  switch (value) {
    case 2: return 'bg-[#eee4da] text-[#776e65]';
    case 4: return 'bg-[#ede0c8] text-[#776e65]';
    case 8: return 'bg-[#f2b179] text-[#f9f6f2]';
    case 16: return 'bg-[#f59563] text-[#f9f6f2]';
    case 32: return 'bg-[#f67c5f] text-[#f9f6f2]';
    case 64: return 'bg-[#f65e3b] text-[#f9f6f2]';
    case 128: return 'bg-[#edcf72] text-[#f9f6f2] shadow-[0_0_10px_#edcf72,inset_0_0_10px_white]';
    case 256: return 'bg-[#edcc61] text-[#f9f6f2] shadow-[0_0_15px_#edcc61,inset_0_0_10px_white]';
    case 512: return 'bg-[#edc850] text-[#f9f6f2] shadow-[0_0_20px_#edc850,inset_0_0_15px_white]';
    case 1024: return 'bg-[#edc53f] text-[#f9f6f2] shadow-[0_0_25px_#edc53f,inset_0_0_15px_white] text-4xl';
    case 2048: return 'bg-[#edc22e] text-[#f9f6f2] shadow-[0_0_30px_#edc22e,inset_0_0_20px_white] text-4xl';
    default: 
      if (value > 2048) return 'bg-[#3c3a32] text-[#f9f6f2] text-4xl';
      return isLight ? 'bg-[#cdc1b4]/30 text-transparent' : 'bg-[#3d3a33]/30 text-transparent'; // empty
  }
};

let idCounter = 0;

export default function Game2048() {
  const { themeMode } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [grid, setGrid] = useState<(Tile | null)[][]>(() => getEmptyGrid());
  const [score, setScore] = useState(0);
  const [bestScore, setBestScore] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [gameWon, setGameWon] = useState(false);
  const [hasContinued, setHasContinued] = useState(false);

  useEffect(() => {
    const savedBest = localStorage.getItem('2048-best');
    if (savedBest) setBestScore(parseInt(savedBest, 10));
    initGame();
  }, []);

  useEffect(() => {
    if (score > bestScore) {
      setBestScore(score);
      localStorage.setItem('2048-best', score.toString());
    }
  }, [score, bestScore]);

  function getEmptyGrid(): (Tile | null)[][] {
    return Array(4).fill(null).map(() => Array(4).fill(null));
  }

  const addRandomTile = (currentGrid: (Tile | null)[][]) => {
    const emptyCells: {r: number, c: number}[] = [];
    for (let r = 0; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        if (!currentGrid[r][c]) emptyCells.push({r, c});
      }
    }
    if (emptyCells.length === 0) return currentGrid;

    const { r, c } = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    const newGrid = [...currentGrid.map(row => [...row])];
    newGrid[r][c] = {
      id: idCounter++,
      value: Math.random() < 0.9 ? 2 : 4,
      isNew: true
    };
    return newGrid;
  };

  const initGame = () => {
    let newGrid = getEmptyGrid();
    newGrid = addRandomTile(newGrid);
    newGrid = addRandomTile(newGrid);
    setGrid(newGrid);
    setScore(0);
    setGameOver(false);
    setGameWon(false);
    setHasContinued(false);
  };

  const checkGameOver = (currentGrid: (Tile | null)[][]) => {
    for (let r = 0; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        if (!currentGrid[r][c]) return false;
        if (c < 3 && currentGrid[r][c]?.value === currentGrid[r][c+1]?.value) return false;
        if (r < 3 && currentGrid[r][c]?.value === currentGrid[r+1][c]?.value) return false;
      }
    }
    return true;
  };

  const slideRow = (row: (Tile | null)[]) => {
    let arr = row.filter(val => val !== null) as Tile[];
    let scoreDelta = 0;

    // reset merged flags
    arr = arr.map(t => ({...t, isMerged: false, isNew: false}));

    for (let i = 0; i < arr.length - 1; i++) {
      if (arr[i].value === arr[i + 1].value) {
        arr[i] = {
          id: idCounter++,
          value: arr[i].value * 2,
          isMerged: true
        };
        scoreDelta += arr[i].value;
        if (arr[i].value === 2048 && !hasContinued) {
          setGameWon(true);
        }
        arr.splice(i + 1, 1);
      }
    }

    while (arr.length < 4) {
      arr.push(null as any);
    }
    return { newRow: arr, scoreDelta };
  };

  const handleMove = useCallback((direction: 'up' | 'down' | 'left' | 'right') => {
    if (gameOver || (gameWon && !hasContinued)) return;

    setGrid(prevGrid => {
      let newGrid = prevGrid.map(row => [...row]);
      let totalScoreDelta = 0;
      let moved = false;

      if (direction === 'left' || direction === 'right') {
        for (let r = 0; r < 4; r++) {
          let row = newGrid[r];
          if (direction === 'right') row.reverse();
          const { newRow, scoreDelta } = slideRow(row);
          if (direction === 'right') newRow.reverse();

          for (let c = 0; c < 4; c++) {
            if (newGrid[r][c]?.id !== newRow[c]?.id) moved = true;
          }
          newGrid[r] = newRow;
          totalScoreDelta += scoreDelta;
        }
      } else {
        for (let c = 0; c < 4; c++) {
          let col = [newGrid[0][c], newGrid[1][c], newGrid[2][c], newGrid[3][c]];
          if (direction === 'down') col.reverse();
          const { newRow, scoreDelta } = slideRow(col);
          if (direction === 'down') newRow.reverse();

          for (let r = 0; r < 4; r++) {
            if (newGrid[r][c]?.id !== newRow[r]?.id) moved = true;
            newGrid[r][c] = newRow[r];
          }
          totalScoreDelta += scoreDelta;
        }
      }

      if (moved) {
        newGrid = addRandomTile(newGrid);
        setScore(s => s + totalScoreDelta);
        if (checkGameOver(newGrid)) {
          setGameOver(true);
        }
        return newGrid;
      }
      return prevGrid;
    });
  }, [gameOver, gameWon, hasContinued]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.preventDefault();
        const dirMap: Record<string, 'up'|'down'|'left'|'right'> = {
          'ArrowUp': 'up',
          'ArrowDown': 'down',
          'ArrowLeft': 'left',
          'ArrowRight': 'right'
        };
        handleMove(dirMap[e.key]);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleMove]);

  // Touch handlers for swipe
  const [touchStart, setTouchStart] = useState<{x: number, y: number} | null>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchStart({ x: e.touches[0].clientX, y: e.touches[0].clientY });
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart) return;
    const touchEnd = { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
    const dx = touchEnd.x - touchStart.x;
    const dy = touchEnd.y - touchStart.y;

    if (Math.abs(dx) > Math.abs(dy)) {
      if (Math.abs(dx) > 30) handleMove(dx > 0 ? 'right' : 'left');
    } else {
      if (Math.abs(dy) > 30) handleMove(dy > 0 ? 'down' : 'up');
    }
    setTouchStart(null);
  };

  return (
    <div className={`flex flex-col items-center justify-center h-full w-full select-none ${isLight ? 'bg-[#faf8ef] text-[#776e65]' : 'bg-[#1e1e1e] text-[#faf8ef]'}`}>
      <div className="w-full max-w-[500px] p-6">

        {/* Header */}
        <div className="flex justify-between items-end mb-8">
          <h1 className="text-6xl font-extrabold" style={{ color: isLight ? '#776e65' : '#e4e4e4' }}>2048</h1>
          <div className="flex gap-2">
            <div className={`flex flex-col items-center justify-center px-4 py-1.5 rounded-md ${isLight ? 'bg-[#bbada0] text-white' : 'bg-[#3d3a33] text-white'}`}>
              <span className={`text-[10px] font-bold uppercase ${isLight ? 'text-[#eee4da]' : 'text-gray-400'}`}>Score</span>
              <span className="font-bold text-xl leading-none">{score}</span>
            </div>
            <div className={`flex flex-col items-center justify-center px-4 py-1.5 rounded-md ${isLight ? 'bg-[#bbada0] text-white' : 'bg-[#3d3a33] text-white'}`}>
              <span className={`text-[10px] font-bold uppercase ${isLight ? 'text-[#eee4da]' : 'text-gray-400'}`}>Best</span>
              <span className="font-bold text-xl leading-none">{bestScore}</span>
            </div>
          </div>
        </div>

        <div className="flex justify-between items-center mb-8">
          <p className="font-medium text-lg leading-tight">
            Join the numbers and get to the <strong className="font-extrabold">2048 tile!</strong>
          </p>
          <button 
            onClick={initGame}
            className="flex items-center gap-2 px-5 py-3 rounded-md bg-[#8f7a66] hover:bg-[#9f8b77] text-[#f9f6f2] font-bold transition-colors shadow-sm whitespace-nowrap"
          >
            <RotateCcw size={18} /> New Game
          </button>
        </div>

        {/* Game Board */}
        <div 
          className={`relative p-3 rounded-xl touch-none ${isLight ? 'bg-[#bbada0]' : 'bg-[#2d2a24]'}`}
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          {/* Overlay for Game Over / Win */}
          <AnimatePresence>
            {(gameOver || (gameWon && !hasContinued)) && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 z-50 rounded-xl flex flex-col items-center justify-center bg-[#eee4da]/70 backdrop-blur-sm"
              >
                <h2 className="text-5xl font-extrabold text-[#776e65] mb-6 drop-shadow-md">
                  {gameWon && !hasContinued ? 'You Win!' : 'Game Over!'}
                </h2>
                <div className="flex gap-4">
                  <button 
                    onClick={initGame}
                    className="px-6 py-3 rounded-md bg-[#8f7a66] hover:bg-[#9f8b77] text-[#f9f6f2] font-bold text-lg transition-colors shadow-lg"
                  >
                    Try again
                  </button>
                  {gameWon && !hasContinued && (
                    <button 
                      onClick={() => setHasContinued(true)}
                      className="px-6 py-3 rounded-md bg-[#edc22e] hover:bg-[#f3d15b] text-[#f9f6f2] font-bold text-lg transition-colors shadow-lg"
                    >
                      Keep going
                    </button>
                  )}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="grid grid-cols-4 gap-3 relative">
            {/* Background Cells */}
            {Array(16).fill(0).map((_, i) => (
              <div key={i} className={`aspect-square rounded-md ${isLight ? 'bg-[#cdc1b4]' : 'bg-[#3d3a33]'}`}></div>
            ))}

            {/* Active Tiles */}
            {grid.map((row, r) => (
              row.map((tile, c) => {
                if (!tile) return null;
                return (
                  <motion.div
                    key={tile.id}
                    layoutId={`tile-${tile.id}`}
                    initial={tile.isNew ? { scale: 0, opacity: 0 } : false}
                    animate={{ 
                      scale: tile.isMerged ? [1, 1.15, 1] : 1,
                      opacity: 1
                    }}
                    transition={{ 
                      default: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
                      scale: tile.isMerged ? { duration: 0.2, times: [0, 0.5, 1] } : { type: 'spring', stiffness: 400, damping: 30 }
                    }}
                    className={`absolute rounded-md flex items-center justify-center font-bold text-3xl shadow-sm ${getTileColors(tile.value, isLight)}`}
                    style={{
                      width: 'calc(25% - 9px)',
                      height: 'calc(25% - 9px)',
                      top: `calc(${r * 25}% + ${r * 3}px)`,
                      left: `calc(${c * 25}% + ${c * 3}px)`,
                    }}
                  >
                    {tile.value}
                  </motion.div>
                );
              })
            ))}
          </div>
        </div>

        <p className={`mt-6 text-sm text-center ${isLight ? 'text-[#776e65]/70' : 'text-gray-500'}`}>
          <strong>HOW TO PLAY:</strong> Use your <strong className="text-current">arrow keys</strong> or <strong className="text-current">swipe</strong> to move the tiles. Tiles with the same number merge into one when they touch. Add them up to reach <strong>2048!</strong>
        </p>
      </div>
    </div>
  );
}

src/components/apps/MagicEraser.tsx.content:
'use client';

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { motion, AnimatePresence } from 'framer-motion';
import { UploadCloud, Download, Loader2, Sparkles, RefreshCcw, Image as ImageIcon, Wand2, Crop, RotateCcw } from 'lucide-react';
import { removeBackground } from '@imgly/background-removal';
import FilerobotImageEditor from './FilerobotWrapper';

export default function MagicEraser() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [currentImage, setCurrentImage] = useState<string | null>(null);
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [fileName, setFileName] = useState<string>('image.png');

  const [isProcessingBg, setIsProcessingBg] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [progressText, setProgressText] = useState('');
  const [isDragging, setIsDragging] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditing) {
      // Suppress the known 'active' attribute warning from react-filerobot-image-editor
      const originalError = console.error;
      console.error = (...args) => {
        if (typeof args[0] === 'string' && args[0].includes('for a non-boolean attribute `active`')) {
          return;
        }
        originalError.call(console, ...args);
      };
      return () => {
        console.error = originalError;
      };
    }
  }, [isEditing]);

  const handleFile = (file: File) => {
    if (!file.type.startsWith('image/')) {
      alert('Please upload a valid image file (JPG, PNG)');
      return;
    }
    setFileName(file.name);
    const url = URL.createObjectURL(file);
    setOriginalImage(url);
    setCurrentImage(url);
  };

  const processBackgroundRemoval = async () => {
    if (!currentImage) return;
    try {
      setIsProcessingBg(true);
      setProgressText('Downloading AI model (first time only)...');

      const config = {
        progress: (key: string, current: number, total: number) => {
          if (key === 'compute:inference') {
            setProgressText(`Processing pixels... ${Math.round((current / total) * 100)}%`);
          } else {
            setProgressText(`Loading AI... ${key}`);
          }
        }
      };

      // We need to convert the object URL back to a blob to feed into imgly
      const response = await fetch(currentImage);
      const blobToProcess = await response.blob();

      const resultBlob = await removeBackground(blobToProcess, config);
      const url = URL.createObjectURL(resultBlob);
      setCurrentImage(url);
    } catch (err) {
      console.error(err);
      alert('Failed to process image. Please try another image.');
    } finally {
      setIsProcessingBg(false);
    }
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const reset = () => {
    setCurrentImage(null);
    setOriginalImage(null);
    setIsEditing(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const revertToOriginal = () => {
    if (originalImage) {
      setCurrentImage(originalImage);
    }
  };

  return (
    <div className={`flex flex-col h-full w-full ${isLight ? 'bg-slate-50 text-slate-900' : 'bg-slate-900 text-white'}`}>

      {/* Header */}
      <div className={`px-6 py-4 border-b flex-shrink-0 flex items-center justify-between
        ${isLight ? 'bg-white border-slate-200' : 'bg-[#151c2c] border-white/10'}`}>
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-xl bg-gradient-to-br ${accentColor} text-white shadow-lg`}>
            <Wand2 size={24} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">Image Studio</h1>
            <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>AI Eraser & Advanced Editor</p>
          </div>
        </div>
        {currentImage && !isEditing && !isProcessingBg && (
          <div className="flex gap-2">
            <button 
              onClick={revertToOriginal}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors
                ${isLight ? 'bg-slate-100 hover:bg-slate-200 text-slate-700' : 'bg-white/10 hover:bg-white/20 text-white'}`}
            >
              <RotateCcw size={16} /> Revert
            </button>
            <button 
              onClick={reset}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors
                ${isLight ? 'bg-slate-100 hover:bg-slate-200 text-slate-700' : 'bg-white/10 hover:bg-white/20 text-white'}`}
            >
              <RefreshCcw size={16} /> New
            </button>
          </div>
        )}
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-hidden relative flex flex-col items-center justify-center">

        <AnimatePresence mode="wait">
          {!currentImage ? (
            // Dropzone
            <motion.div 
              key="dropzone"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={onDrop}
              onClick={() => fileInputRef.current?.click()}
              className={`w-full max-w-2xl aspect-video rounded-3xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all m-8
                ${isDragging 
                  ? 'border-[var(--theme-accent,currentColor)] bg-[var(--theme-accent,currentColor)]/10 scale-105' 
                  : (isLight ? 'border-slate-300 hover:border-slate-400 bg-white' : 'border-white/20 hover:border-white/30 bg-black/20')}`}
            >
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={(e) => e.target.files && handleFile(e.target.files[0])} 
                accept="image/*" 
                className="hidden" 
              />
              <UploadCloud size={48} className={`mb-4 ${isLight ? 'text-slate-400' : 'text-slate-500'}`} />
              <h2 className="text-xl font-bold mb-2">Drop an image here to start</h2>
              <p className={`text-sm ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>or click to browse from your computer</p>
            </motion.div>
          ) : isProcessingBg ? (
            // Processing Background
            <motion.div 
              key="processing"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex flex-col items-center justify-center text-center max-w-md p-8"
            >
              <div className="relative mb-8">
                <div className={`absolute inset-0 blur-xl opacity-50 bg-gradient-to-r ${accentColor} animate-pulse rounded-full`}></div>
                <Loader2 size={64} className="animate-spin relative z-10 text-white mix-blend-difference" />
              </div>
              <h2 className="text-2xl font-bold mb-3">Removing Background...</h2>
              <p className={`text-sm font-medium ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>{progressText}</p>
              <p className={`text-xs mt-6 max-w-xs leading-relaxed ${isLight ? 'text-slate-400' : 'text-slate-500'}`}>
                Running entirely in your browser using local AI WebAssembly.
              </p>
            </motion.div>
          ) : isEditing ? (
            // Filerobot Editor
            <motion.div 
              key="editor"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="w-full h-full"
            >
              <FilerobotImageEditor
                source={currentImage}
                savingPixelRatio={4}
                previewPixelRatio={1}
                onSave={(editedImageObject, designState) => {
                  setCurrentImage(editedImageObject.imageBase64 as string);
                  setIsEditing(false);
                }}
                onClose={() => setIsEditing(false)}
                annotationsCommon={{
                  fill: '#ff0000',
                }}
                Text={{ text: 'Filerobot...' }}
                Rotate={{ angle: 90, componentType: 'slider' }}
                Crop={{
                  presetsItems: [
                    {
                      titleKey: 'classicTv',
                      descriptionKey: '4:3',
                      ratio: 4 / 3,
                    },
                    {
                      titleKey: 'cinemascope',
                      descriptionKey: '21:9',
                      ratio: 21 / 9,
                    },
                  ],
                }}
                tabsIds={['Adjust', 'Annotate', 'Watermark', 'Filters', 'Finetune']} 
                defaultTabId="Adjust"
                defaultToolId="Crop"
              />
            </motion.div>
          ) : (
            // Studio Workspace View
            <motion.div 
              key="workspace"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="w-full flex flex-col h-full"
            >
              {/* Toolbar */}
              <div className={`flex gap-4 p-4 border-b justify-center items-center shadow-sm z-10
                ${isLight ? 'bg-slate-100 border-slate-200' : 'bg-black/20 border-white/5'}`}>

                <button 
                  onClick={processBackgroundRemoval}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-xl font-bold text-white shadow-md transition-transform hover:scale-105 active:scale-95 bg-gradient-to-r ${accentColor}`}
                >
                  <Sparkles size={18} /> Remove Background
                </button>

                <div className={`w-px h-8 ${isLight ? 'bg-slate-300' : 'bg-white/20'}`}></div>

                <button 
                  onClick={() => setIsEditing(true)}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-xl font-bold shadow-md transition-transform hover:scale-105 active:scale-95 border
                    ${isLight ? 'bg-white border-slate-300 text-slate-800' : 'bg-slate-800 border-slate-600 text-white'}`}
                >
                  <Crop size={18} /> Edit Image
                </button>

                <div className={`w-px h-8 ${isLight ? 'bg-slate-300' : 'bg-white/20'}`}></div>

                <a 
                  href={currentImage} 
                  download={`edited-${fileName}`}
                  className={`flex items-center gap-2 px-5 py-2.5 rounded-xl font-bold shadow-md transition-transform hover:scale-105 active:scale-95 border
                    ${isLight ? 'bg-white border-slate-300 text-slate-800' : 'bg-slate-800 border-slate-600 text-white'}`}
                >
                  <Download size={18} /> Download
                </a>
              </div>

              {/* Canvas Preview */}
              <div className="flex-1 p-8 flex items-center justify-center overflow-auto relative">
                {/* Checkerboard pattern so transparency is visible */}
                <div className="absolute inset-8 z-0 rounded-2xl opacity-50" style={{
                  backgroundImage: 'linear-gradient(45deg, #ccc 25%, transparent 25%), linear-gradient(-45deg, #ccc 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #ccc 75%), linear-gradient(-45deg, transparent 75%, #ccc 75%)',
                  backgroundSize: '20px 20px',
                  backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px'
                }}></div>
                <img 
                  src={currentImage} 
                  alt="Current Workspace" 
                  className="max-w-full max-h-full object-contain relative z-10 drop-shadow-2xl rounded-lg border border-white/20" 
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>

      </div>
    </div>
  );
}

src/components/apps/QRStudio.tsx.content:
'use client';

import React, { useState, useRef } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { QrCode, Download, Link, Type, Palette, Image as ImageIcon } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';

export default function QRStudio() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [qrValue, setQrValue] = useState('https://rohitpancholi.com');
  const [fgColor, setFgColor] = useState('#000000');
  const [bgColor, setBgColor] = useState('#ffffff');
  const [logoUrl, setLogoUrl] = useState<string | null>(null);

  const svgRef = useRef<SVGSVGElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svg = svgRef.current;
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    img.onload = () => {
      // Create padding for the downloaded image
      const padding = 40;
      canvas.width = img.width + padding * 2;
      canvas.height = img.height + padding * 2;

      if (ctx) {
        ctx.fillStyle = bgColor;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, padding, padding);

        const pngFile = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.download = "QR_Code.png";
        downloadLink.href = `${pngFile}`;
        downloadLink.click();
      }
    };

    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setLogoUrl(url);
    }
  };

  return (
    <div className={`flex flex-col h-full w-full ${isLight ? 'bg-slate-50 text-slate-900' : 'bg-slate-900 text-white'}`}>

      {/* Header */}
      <div className={`px-6 py-4 border-b flex-shrink-0 flex items-center justify-between
        ${isLight ? 'bg-white border-slate-200' : 'bg-[#151c2c] border-white/10'}`}>
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-xl bg-gradient-to-br ${accentColor} text-white shadow-lg`}>
            <QrCode size={24} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">QR Studio</h1>
            <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Custom QR Code Generator</p>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col md:flex-row overflow-hidden">

        {/* Left Side: Controls */}
        <div className={`w-full md:w-1/2 p-6 overflow-y-auto border-r ${isLight ? 'border-slate-200' : 'border-white/10'}`}>
          <div className="space-y-6">

            {/* Input Data */}
            <div>
              <label className="flex items-center gap-2 text-sm font-bold mb-2">
                <Link size={16} /> Enter URL or Text
              </label>
              <textarea 
                value={qrValue}
                onChange={(e) => setQrValue(e.target.value)}
                placeholder="https://example.com"
                className={`w-full p-4 rounded-xl border focus:ring-2 focus:outline-none transition-shadow resize-none h-32
                  ${isLight 
                    ? 'bg-white border-slate-300 focus:ring-blue-500/20' 
                    : 'bg-black/20 border-white/10 focus:ring-blue-500/50'}`}
              />
            </div>

            {/* Colors */}
            <div>
              <label className="flex items-center gap-2 text-sm font-bold mb-3">
                <Palette size={16} /> Customize Colors
              </label>
              <div className="flex gap-4">
                <div className={`flex-1 p-3 rounded-xl border flex items-center justify-between
                  ${isLight ? 'bg-white border-slate-200' : 'bg-black/20 border-white/10'}`}>
                  <span className="text-sm font-medium">Foreground</span>
                  <input 
                    type="color" 
                    value={fgColor} 
                    onChange={(e) => setFgColor(e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer border-0 p-0"
                  />
                </div>
                <div className={`flex-1 p-3 rounded-xl border flex items-center justify-between
                  ${isLight ? 'bg-white border-slate-200' : 'bg-black/20 border-white/10'}`}>
                  <span className="text-sm font-medium">Background</span>
                  <input 
                    type="color" 
                    value={bgColor} 
                    onChange={(e) => setBgColor(e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer border-0 p-0"
                  />
                </div>
              </div>
            </div>

            {/* Logo Upload */}
            <div>
              <label className="flex items-center gap-2 text-sm font-bold mb-3">
                <ImageIcon size={16} /> Center Logo (Optional)
              </label>
              <div className={`p-4 rounded-xl border border-dashed flex flex-col items-center justify-center gap-2
                ${isLight ? 'bg-slate-50 border-slate-300' : 'bg-white/5 border-white/20'}`}>
                {logoUrl ? (
                  <div className="flex items-center justify-between w-full">
                    <img src={logoUrl} alt="Logo" className="w-10 h-10 object-contain bg-white rounded p-1" />
                    <button 
                      onClick={() => setLogoUrl(null)}
                      className="text-xs text-red-500 hover:underline font-medium"
                    >
                      Remove Logo
                    </button>
                  </div>
                ) : (
                  <>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      onChange={handleLogoUpload} 
                      accept="image/*" 
                      className="hidden" 
                    />
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className={`text-sm font-medium px-4 py-2 rounded-lg transition-colors
                        ${isLight ? 'bg-slate-200 hover:bg-slate-300' : 'bg-white/10 hover:bg-white/20'}`}
                    >
                      Upload Image
                    </button>
                  </>
                )}
              </div>
            </div>

          </div>
        </div>

        {/* Right Side: Preview & Download */}
        <div className={`w-full md:w-1/2 p-8 flex flex-col items-center justify-center relative
          ${isLight ? 'bg-slate-100/50' : 'bg-black/20'}`}>

          <div className={`p-8 rounded-3xl shadow-2xl transition-all hover:scale-105 relative group
            ${isLight ? 'bg-white' : 'bg-white'}`}>
            <QRCodeSVG 
              value={qrValue || ' '} 
              size={250} 
              fgColor={fgColor} 
              bgColor={bgColor}
              level="H"
              includeMargin={false}
              ref={svgRef}
              imageSettings={logoUrl ? {
                src: logoUrl,
                x: undefined,
                y: undefined,
                height: 50,
                width: 50,
                excavate: true,
              } : undefined}
            />
          </div>

          <button 
            onClick={handleDownload}
            disabled={!qrValue}
            className={`mt-10 flex items-center gap-2 px-8 py-4 rounded-2xl font-bold text-white shadow-xl transition-all 
              ${!qrValue ? 'opacity-50 cursor-not-allowed grayscale' : 'hover:scale-105 active:scale-95 hover:shadow-2xl'} 
              bg-gradient-to-r ${accentColor}`}
          >
            <Download size={20} /> Download PNG
          </button>
        </div>

      </div>
    </div>
  );
}

