'use client';
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useSettingsStore } from '@/store/useSettingsStore';
import { ChevronRight, ChevronLeft, Sparkles, Bot, FileText, Languages, Settings, Layout } from 'lucide-react';
import { useWindowStore } from '@/store/useWindowStore';

const SLIDES = [
  {
    id: 'welcome',
    title: 'Welcome to Portfolio OS',
    description: 'Experience a fully interactive, web-based operating system designed to showcase my skills, projects, and personality in a unique way.',
    icon: Sparkles,
    color: 'text-yellow-500'
  },
  {
    id: 'chatbot',
    title: 'Virtual Rohit',
    description: 'An intelligent AI assistant built right into the OS. You can even use Voice Commands to interact with it directly!',
    icon: Bot,
    color: 'text-pink-500'
  },
  {
    id: 'resume',
    title: 'Interactive Resume',
    description: 'View my professional experience, skills, and education in a clean, beautifully formatted document viewer.',
    icon: FileText,
    color: 'text-emerald-500'
  },
  {
    id: 'translate',
    title: 'Real-time Translation',
    description: 'Test out the built-in translation app that dynamically translates text across multiple languages with a sleek interface.',
    icon: Languages,
    color: 'text-blue-500'
  },
  {
    id: 'settings',
    title: 'Deep Customization',
    description: 'Make the OS yours. Change themes, pick vibrant accent colors, and choose from gorgeous ultra-HD macOS wallpapers.',
    icon: Settings,
    color: 'text-slate-500'
  },
  {
    id: 'windows',
    title: 'Window Management',
    description: 'Drag windows around, minimize them to the dock, or maximize them. Enjoy the fluid, physics-based Framer Motion animations.',
    icon: Layout,
    color: 'text-purple-500'
  }
];

export default function Tour() {
  const { themeMode } = useSettingsStore();
  const { closeApp } = useWindowStore();
  const [currentSlide, setCurrentSlide] = useState(0);
  const isLight = themeMode === 'light';

  const nextSlide = () => {
    if (currentSlide < SLIDES.length - 1) {
      setCurrentSlide(prev => prev + 1);
    } else {
      closeApp('tour');
    }
  };

  const prevSlide = () => {
    if (currentSlide > 0) {
      setCurrentSlide(prev => prev - 1);
    }
  };

  const slide = SLIDES[currentSlide];

  return (
    <div className={`flex flex-col h-full w-full overflow-hidden transition-colors ${isLight ? 'bg-slate-50/90 text-slate-900' : 'bg-slate-900/90 text-white'}`}>

      {/* Main Content Area */}
      <div className="flex-1 relative flex flex-col items-center justify-center p-8 text-center overflow-hidden">

        <AnimatePresence mode="wait">
          <motion.div
            key={slide.id}
            initial={{ opacity: 0, x: 50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -50 }}
            transition={{ duration: 0.3, ease: 'easeInOut' }}
            className="flex flex-col items-center max-w-md"
          >
            <div className={`w-24 h-24 rounded-3xl flex items-center justify-center mb-8 shadow-xl border ${isLight ? 'bg-white border-slate-200' : 'bg-black/50 border-white/10'}`}>
              <slide.icon size={48} className={slide.color} />
            </div>

            <h2 className="text-3xl font-bold mb-4">{slide.title}</h2>
            <p className={`text-lg leading-relaxed ${isLight ? 'text-slate-600' : 'text-slate-300'}`}>
              {slide.description}
            </p>
          </motion.div>
        </AnimatePresence>

      </div>

      {/* Footer Navigation */}
      <div className={`h-20 flex items-center justify-between px-8 border-t ${isLight ? 'bg-slate-100/50 border-slate-200/50' : 'bg-black/20 border-white/10'}`}>

        {/* Progress Dots */}
        <div className="flex gap-2">
          {SLIDES.map((_, idx) => (
            <div 
              key={idx} 
              className={`h-2.5 rounded-full transition-all duration-300 ${
                idx === currentSlide 
                  ? (isLight ? 'w-8 bg-blue-500' : 'w-8 bg-blue-400') 
                  : (isLight ? 'w-2.5 bg-slate-300' : 'w-2.5 bg-white/20')
              }`}
            />
          ))}
        </div>

        {/* Controls */}
        <div className="flex gap-3">
          <button 
            onClick={prevSlide}
            disabled={currentSlide === 0}
            className={`px-4 py-2 rounded-xl flex items-center gap-1 transition-colors disabled:opacity-30
              ${isLight ? 'hover:bg-slate-200 text-slate-700' : 'hover:bg-white/10 text-slate-300'}`}
          >
            <ChevronLeft size={18} /> Back
          </button>

          <button 
            onClick={nextSlide}
            className="px-5 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-xl flex items-center gap-1 font-medium transition-colors shadow-lg shadow-blue-500/20"
          >
            {currentSlide === SLIDES.length - 1 ? 'Get Started' : 'Next'} <ChevronRight size={18} />
          </button>
        </div>
      </div>

    </div>
  );
}

src/components/apps/Translator.tsx.content:
'use client';
import { useState, useEffect, useRef } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { ArrowRightLeft, Languages, Loader2, Volume2, Copy, Check, Mic } from 'lucide-react';

const LANGUAGES = {
  auto: 'Detect Language',
  en: 'English',
  hi: 'Hindi',
  es: 'Spanish',
  fr: 'French',
  de: 'German',
  ar: 'Arabic',
  ja: 'Japanese',
  zh: 'Chinese',
  it: 'Italian',
  ru: 'Russian',
  pt: 'Portuguese',
  ko: 'Korean',
};

export default function Translator() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [sourceLang, setSourceLang] = useState('auto');
  const [targetLang, setTargetLang] = useState('hi'); // Default translate to Hindi
  const [sourceText, setSourceText] = useState('');
  const [translatedText, setTranslatedText] = useState('');
  const [isTranslating, setIsTranslating] = useState(false);
  const [copied, setCopied] = useState(false);
  const [detectedLang, setDetectedLang] = useState('');
  const [isListening, setIsListening] = useState(false);

  const debounceTimer = useRef<NodeJS.Timeout | null>(null);

  const startListening = () => {
    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = sourceLang !== 'auto' ? sourceLang : 'en-US';
    recognition.interimResults = true;

    recognition.onstart = () => setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = Array.from(event.results)
        .map((result: any) => result[0])
        .map((result: any) => result.transcript)
        .join('');
      setSourceText(transcript);
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error", event.error);
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognition.start();
  };

  const speakText = (text: string, lang: string) => {
    if (!text) return;
    window.speechSynthesis.cancel(); // Stop any currently playing speech
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang;
    window.speechSynthesis.speak(utterance);
  };

  const handleTranslate = async (text: string, source: string, target: string) => {
    if (!text.trim()) {
      setTranslatedText('');
      setDetectedLang('');
      return;
    }

    setIsTranslating(true);
    try {
      const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=${source}&tl=${target}&dt=t&q=${encodeURIComponent(text)}`;
      const res = await fetch(url);
      const data = await res.json();

      let finalTranslation = '';
      if (data && data[0]) {
        data[0].forEach((item: any) => {
          if (item[0]) finalTranslation += item[0];
        });
      }

      setTranslatedText(finalTranslation);

      // data[2] contains detected language if source was 'auto'
      if (source === 'auto' && data[2]) {
        setDetectedLang(data[2]);
      } else {
        setDetectedLang('');
      }

    } catch (error) {
      console.error('Translation error:', error);
      setTranslatedText('Error translating text. Please try again.');
    } finally {
      setIsTranslating(false);
    }
  };

  // Debounce the translation input
  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);

    debounceTimer.current = setTimeout(() => {
      handleTranslate(sourceText, sourceLang, targetLang);
    }, 600);

    return () => {
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
    };
  }, [sourceText, sourceLang, targetLang]);

  const swapLanguages = () => {
    if (sourceLang === 'auto') {
      if (detectedLang) {
        setSourceLang(targetLang);
        setTargetLang(detectedLang);
      } else {
        // Can't really swap auto if we haven't detected anything, default to English
        setSourceLang(targetLang);
        setTargetLang('en');
      }
    } else {
      setSourceLang(targetLang);
      setTargetLang(sourceLang);
    }
    setSourceText(translatedText);
  };

  const copyToClipboard = () => {
    if (!translatedText) return;
    navigator.clipboard.writeText(translatedText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={`flex flex-col h-full w-full font-sans transition-colors ${isLight ? 'bg-slate-50/90 text-slate-900' : 'bg-slate-900/90 text-slate-100'}`}>

      {/* Header */}
      <div className={`flex items-center px-6 py-4 border-b ${isLight ? 'border-slate-200 bg-white/50' : 'border-white/10 bg-black/20'}`}>
        <div className={`p-2 rounded-lg bg-gradient-to-br ${accentColor} mr-4 shadow-md`}>
          <Languages className="w-5 h-5 text-white" />
        </div>
        <div>
          <h2 className="text-xl font-bold tracking-tight">AI Translator</h2>
          <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Powered by Neural Machine Translation</p>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col md:flex-row p-6 gap-4 overflow-hidden">

        {/* Source Panel */}
        <div className={`flex-1 flex flex-col rounded-2xl border shadow-sm overflow-hidden transition-colors ${isLight ? 'bg-white border-slate-200' : 'bg-slate-950/50 border-white/10'}`}>
          {/* Controls */}
          <div className={`flex items-center p-3 border-b ${isLight ? 'border-slate-100 bg-slate-50/50' : 'border-white/5 bg-black/20'}`}>
            <select 
              value={sourceLang} 
              onChange={(e) => setSourceLang(e.target.value)}
              className={`font-semibold bg-transparent outline-none px-2 py-1 rounded-md text-sm cursor-pointer hover:bg-black/5 dark:hover:bg-white/5`}
            >
              {Object.entries(LANGUAGES).map(([code, name]) => (
                <option key={code} value={code} className="text-black">{name}</option>
              ))}
            </select>
            {sourceLang === 'auto' && detectedLang && LANGUAGES[detectedLang as keyof typeof LANGUAGES] && (
              <span className={`text-xs ml-2 px-2 py-1 rounded-full font-medium ${isLight ? 'bg-indigo-100 text-indigo-700' : 'bg-indigo-500/20 text-indigo-300'}`}>
                Detected: {LANGUAGES[detectedLang as keyof typeof LANGUAGES]}
              </span>
            )}
          </div>

          {/* Text Area */}
          <textarea
            value={sourceText}
            onChange={(e) => setSourceText(e.target.value)}
            placeholder="Enter text to translate..."
            className="flex-1 w-full resize-none bg-transparent p-5 outline-none text-lg placeholder:text-slate-400/60"
            spellCheck="false"
          />

          {/* Footer actions */}
          <div className="p-3 flex justify-between items-center text-slate-400">
            <span className="text-xs font-medium px-2">{sourceText.length} characters</span>
            <button 
              onClick={startListening}
              className={`p-2 rounded-full transition-all ${isListening ? 'bg-red-500/20 text-red-500 animate-pulse scale-110' : (isLight ? 'hover:bg-black/5 text-slate-500' : 'hover:bg-white/5 text-slate-400')}`}
              title="Speak to translate"
            >
              <Mic className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Swap Button (Desktop) */}
        <div className="hidden md:flex items-center justify-center -mx-8 z-10">
          <button 
            onClick={swapLanguages}
            className={`p-3 rounded-full shadow-lg border backdrop-blur-md transition-transform hover:scale-110 active:scale-95 ${isLight ? 'bg-white border-slate-200 text-slate-700' : 'bg-slate-800 border-slate-600 text-white'}`}
          >
            <ArrowRightLeft className="w-5 h-5" />
          </button>
        </div>

        {/* Target Panel */}
        <div className={`flex-1 flex flex-col rounded-2xl border shadow-sm overflow-hidden transition-colors ${isLight ? 'bg-slate-50 border-slate-200' : 'bg-black/40 border-white/10'}`}>
          {/* Controls */}
          <div className={`flex items-center p-3 border-b ${isLight ? 'border-slate-200 bg-slate-100/50' : 'border-white/5 bg-black/40'}`}>
            <select 
              value={targetLang} 
              onChange={(e) => setTargetLang(e.target.value)}
              className={`font-semibold bg-transparent outline-none px-2 py-1 rounded-md text-sm cursor-pointer hover:bg-black/5 dark:hover:bg-white/5`}
            >
              {Object.entries(LANGUAGES).filter(([code]) => code !== 'auto').map(([code, name]) => (
                <option key={code} value={code} className="text-black">{name}</option>
              ))}
            </select>
            {isTranslating && (
              <div className="ml-auto flex items-center text-xs text-indigo-500 font-medium">
                <Loader2 className="w-3 h-3 mr-1.5 animate-spin" />
                Translating...
              </div>
            )}
          </div>

          {/* Text Area */}
          <div className="flex-1 w-full relative">
            <textarea
              value={translatedText}
              readOnly
              placeholder="Translation will appear here..."
              className={`w-full h-full resize-none bg-transparent p-5 outline-none text-lg ${isTranslating ? 'opacity-50' : 'opacity-100'}`}
            />
          </div>

          {/* Footer actions */}
          <div className="p-3 flex justify-end items-center gap-2">
            <button 
              onClick={() => speakText(translatedText, targetLang)}
              disabled={!translatedText}
              className={`p-2 rounded-full transition-all ${translatedText ? (isLight ? 'hover:bg-black/5 text-indigo-600' : 'hover:bg-white/5 text-indigo-400') : 'opacity-30 cursor-not-allowed text-slate-500'}`}
              title="Listen to translation"
            >
              <Volume2 className="w-4 h-4" />
            </button>
            <div className={`w-px h-4 mx-1 ${isLight ? 'bg-slate-300' : 'bg-white/10'}`}></div>
            <button 
              onClick={copyToClipboard}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-all ${copied ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' : 'hover:bg-black/5 dark:hover:bg-white/5 text-slate-500 dark:text-slate-400'}`}
            >
              {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
              {copied ? 'Copied!' : 'Copy'}
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}

src/components/apps/VSCode.tsx.content:
'use client';
import { useState, useMemo } from 'react';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { FileCode, FileJson, FileType2, FileText, ChevronRight, ChevronDown, Search, GitBranch, Settings, Info } from 'lucide-react';
import codebaseDataRaw from '@/lib/codebase.json';

type CodebaseFile = {
  content: string;
  language: string;
};

const codebaseData = codebaseDataRaw as Record<string, CodebaseFile>;

const getFileIcon = (filename: string) => {
  if (filename.endsWith('.tsx')) return { icon: FileCode, color: 'text-blue-400' };
  if (filename.endsWith('.ts')) return { icon: FileType2, color: 'text-blue-500' };
  if (filename.endsWith('.js') || filename.endsWith('.mjs') || filename.endsWith('.cjs')) return { icon: FileCode, color: 'text-yellow-300' };
  if (filename.endsWith('.json') || filename.startsWith('.')) return { icon: FileJson, color: 'text-yellow-400' };
  if (filename.endsWith('.md')) return { icon: Info, color: 'text-blue-300' };
  if (filename.endsWith('.css')) return { icon: FileText, color: 'text-cyan-400' };
  return { icon: FileText, color: 'text-slate-400' };
};

export default function VSCode() {
  const filePaths = useMemo(() => Object.keys(codebaseData).sort(), []);

  // Set default active file and open tabs
  const defaultFile = 'src/app/page.tsx';
  const [activeFile, setActiveFile] = useState<string>(codebaseData[defaultFile] ? defaultFile : filePaths[0] || '');
  const [openFiles, setOpenFiles] = useState<string[]>(
    ['src/app/page.tsx', 'src/store/useWindowStore.ts', 'package.json'].filter(p => codebaseData[p])
  );
  const [expandedFolders, setExpandedFolders] = useState<Record<string, boolean>>({});

  const toggleFolder = (folderPath: string) => {
    setExpandedFolders(prev => ({
      ...prev,
      [folderPath]: prev[folderPath] === undefined ? false : !prev[folderPath]
    }));
  };

  const handleFileClick = (path: string) => {
    if (!openFiles.includes(path)) {
      setOpenFiles([...openFiles, path]);
    }
    setActiveFile(path);
  };

  const closeFile = (e: React.MouseEvent, path: string) => {
    e.stopPropagation();
    const newOpenFiles = openFiles.filter(p => p !== path);
    setOpenFiles(newOpenFiles);
    if (activeFile === path) {
      setActiveFile(newOpenFiles.length > 0 ? newOpenFiles[0] : '');
    }
  };

  // Helper to group files by directory for the sidebar
  const directoryTree = useMemo(() => {
    const tree: any = {
      '.git': {},
      '.next': {},
      'node_modules': {},
    };
    filePaths.forEach(path => {
      const parts = path.split('/');
      let current = tree;
      for (let i = 0; i < parts.length - 1; i++) {
        if (!current[parts[i]]) current[parts[i]] = {};
        current = current[parts[i]];
      }
      current[parts[parts.length - 1]] = path; // store full path for leaf nodes
    });
    return tree;
  }, [filePaths]);

  const renderTree = (node: any, level = 0, currentPath = '') => {
    return Object.entries(node).map(([key, value]) => {
      const fullPath = currentPath ? `${currentPath}/${key}` : key;
      if (typeof value === 'string') {
        // It's a file
        const { icon: Icon, color } = getFileIcon(key);
        const isActive = activeFile === value;
        return (
          <div 
            key={value}
            onClick={() => handleFileClick(value)}
            className={`flex items-center px-4 py-1.5 cursor-pointer text-[13px] ${isActive ? 'bg-[#37373d] text-white' : 'hover:bg-[#2a2d2e] text-[#cccccc]'}`}
            style={{ paddingLeft: `${(level + 1) * 12 + 12}px` }}
          >
            <Icon size={16} className={`mr-2 shrink-0 ${color}`} />
            <span className="truncate">{key}</span>
          </div>
        );
      } else {
        // It's a folder
        const isDummy = ['.git', '.next', 'node_modules'].includes(key) && level === 0;
        const isExpanded = isDummy ? false : expandedFolders[fullPath] !== false;

        return (
          <div key={fullPath} className="flex flex-col">
            <div 
              onClick={() => !isDummy && toggleFolder(fullPath)}
              className={`flex items-center px-1 py-1 text-[#cccccc] text-[13px] select-none ${isDummy ? 'cursor-default opacity-80' : 'cursor-pointer hover:bg-[#2a2d2e]'}`}
              style={{ paddingLeft: `${level * 12 + 8}px` }}
            >
              <ChevronRight size={16} className={`mr-1 shrink-0 ${isExpanded ? 'rotate-90' : ''} transition-transform`} /> {key}
            </div>
            {isExpanded && renderTree(value, level + 1, fullPath)}
          </div>
        );
      }
    });
  };

  return (
    <div className="flex h-full w-full flex-col bg-[#1e1e1e] text-[#cccccc] font-sans">
      {/* Activity Bar & Main Content */}
      <div className="flex flex-1 overflow-hidden">

        {/* Activity Bar */}
        <div className="w-12 bg-[#333333] flex flex-col items-center py-4 border-r border-[#252526] shrink-0">
          <button className="p-3 text-white border-l-2 border-blue-500 hover:text-white transition-colors"><FileCode size={24} strokeWidth={1.5} /></button>
          <button className="p-3 text-[#858585] hover:text-white transition-colors"><Search size={24} strokeWidth={1.5} /></button>
          <button className="p-3 text-[#858585] hover:text-white transition-colors"><GitBranch size={24} strokeWidth={1.5} /></button>
          <button className="p-3 text-[#858585] hover:text-white transition-colors mt-auto"><Settings size={24} strokeWidth={1.5} /></button>
        </div>

        {/* Sidebar (File Explorer) */}
        <div className="w-64 bg-[#252526] flex flex-col shrink-0 border-r border-[#1e1e1e]">
          <div className="px-4 py-3 text-[11px] font-bold tracking-wider uppercase text-[#bbbbbb]">Explorer</div>

          <div className="flex flex-col mt-2 flex-1 overflow-y-auto custom-scrollbar">
            <div 
              onClick={() => toggleFolder('root')}
              className="flex items-center px-1 py-1 cursor-pointer hover:bg-[#2a2d2e] font-bold text-sm text-white select-none"
            >
              {expandedFolders['root'] !== false ? <ChevronDown size={16} className="mr-1 shrink-0" /> : <ChevronRight size={16} className="mr-1 shrink-0" />}
              ROHIT-PORTFOLIO-OS
            </div>

            {expandedFolders['root'] !== false && (
              <div className="flex flex-col mt-1 pb-4">
                {renderTree(directoryTree)}
              </div>
            )}
          </div>
        </div>

        {/* Editor Area */}
        <div className="flex-1 flex flex-col bg-[#1e1e1e] overflow-hidden min-w-0">

          {/* Editor Tabs */}
          {openFiles.length > 0 ? (
            <div className="flex bg-[#252526] overflow-x-auto custom-scrollbar shrink-0">
              {openFiles.map((path) => {
                const isActive = activeFile === path;
                const filename = path.split('/').pop() || path;
                const { icon: Icon, color } = getFileIcon(filename);
                return (
                  <div 
                    key={path}
                    onClick={() => setActiveFile(path)}
                    className={`flex items-center px-3 py-2 cursor-pointer text-[13px] border-r border-[#1e1e1e] min-w-[120px] max-w-[200px] group ${isActive ? 'bg-[#1e1e1e] text-white border-t-2 border-t-blue-500' : 'bg-[#2d2d2d] text-[#858585] hover:bg-[#2a2d2e]'}`}
                  >
                    <Icon size={14} className={`mr-2 shrink-0 ${color}`} />
                    <span className="truncate flex-1">{filename}</span>
                    <div 
                      onClick={(e) => closeFile(e, path)}
                      className={`ml-2 w-5 h-5 flex items-center justify-center rounded hover:bg-white/10 ${isActive ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                    >
                      ×
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-[#858585]">
              <FileCode size={64} strokeWidth={1} className="mb-4 opacity-20" />
              <p>Select a file to view code</p>
            </div>
          )}

          {/* Editor Breadcrumbs */}
          {activeFile && codebaseData[activeFile] && (
            <div className="px-4 py-1.5 flex items-center text-[12px] text-[#858585] bg-[#1e1e1e] shadow-sm shrink-0 overflow-hidden whitespace-nowrap">
              <span className="hover:text-white cursor-pointer shrink-0">rohit-portfolio-os</span>
              {activeFile.split('/').map((part, index, arr) => (
                <div key={index} className="flex items-center">
                  <ChevronRight size={14} className="mx-1 opacity-50 shrink-0" />
                  <span className={`${index === arr.length - 1 ? 'text-[#cccccc]' : 'hover:text-white cursor-pointer'}`}>{part}</span>
                </div>
              ))}
            </div>
          )}

          {/* Syntax Highlighter */}
          {activeFile && codebaseData[activeFile] && (
            <div className="flex-1 overflow-auto bg-[#1e1e1e] custom-scrollbar pb-10">
              <SyntaxHighlighter
                language={codebaseData[activeFile].language}
                style={vscDarkPlus}
                customStyle={{
                  margin: 0,
                  padding: '24px 0',
                  background: 'transparent',
                  fontSize: '14px',
                  lineHeight: '1.6',
                  fontFamily: "'JetBrains Mono', 'Fira Code', Consolas, monospace",
                }}
                showLineNumbers={true}
                lineNumberStyle={{ minWidth: '50px', paddingRight: '20px', color: '#6e7681', textAlign: 'right' }}
              >
                {codebaseData[activeFile].content}
              </SyntaxHighlighter>
            </div>
          )}
        </div>

      </div>

      {/* Status Bar */}
      <div className="h-6 bg-[#007acc] text-white flex items-center justify-between px-3 text-[11px] font-medium shrink-0 overflow-hidden">
        <div className="flex items-center space-x-4">
          <span className="flex items-center gap-1 hover:bg-white/20 px-2 py-0.5 rounded cursor-pointer transition-colors whitespace-nowrap"><GitBranch size={12}/> main*</span>
          <span className="hover:bg-white/20 px-2 py-0.5 rounded cursor-pointer transition-colors whitespace-nowrap">0 ⚠  0 ⛔</span>
        </div>
        <div className="flex items-center space-x-4">
          <span className="hover:bg-white/20 px-2 py-0.5 rounded cursor-pointer transition-colors hidden sm:block">UTF-8</span>
          {activeFile && codebaseData[activeFile] && (
            <span className="hover:bg-white/20 px-2 py-0.5 rounded cursor-pointer transition-colors whitespace-nowrap">{codebaseData[activeFile].language.toUpperCase()}</span>
          )}
          <span className="hover:bg-white/20 px-2 py-0.5 rounded cursor-pointer transition-colors hidden sm:block">Prettier</span>
        </div>
      </div>
    </div>
  );
}

